package com.bank.fp;

import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Collectors;

public class FunctionalBenefitsDemo {

    record Trade(String id, BigDecimal amount, String status) {
        boolean isSettled() { return "SETTLED".equals(status); }
    }

    static List<Trade> trades = List.of(
        new Trade("T1", new BigDecimal("245050"), "SETTLED"),
        new Trade("T2", new BigDecimal("176000"), "PENDING"),
        new Trade("T3", new BigDecimal("330150"), "SETTLED"));

    // ═══ BENEFIT 1: IMMUTABILITY — record is immutable ═══
    // Trade fields are final. No setters. Thread-safe by default.

    // ═══ BENEFIT 2: PURE FUNCTIONS — same input → same output ═══
    static BigDecimal calculateTotal(List<Trade> trades) {
        return trades.stream()
            .filter(Trade::isSettled)
            .map(Trade::amount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        // Pure: no external state read or modified. Same trades → same total. Always.
    }

    // ═══ BENEFIT 3: CONCISE CODE ═══
    // 3 lines vs 10 lines of for-loop + if + accumulator

    // ═══ BENEFIT 4: EASIER PARALLELISM ═══
    static BigDecimal calculateTotalParallel(List<Trade> trades) {
        return trades.parallelStream()  // just add .parallel — safe because no shared state!
            .filter(Trade::isSettled)
            .map(Trade::amount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    // ═══ BENEFIT 5: HIGHER-ORDER FUNCTIONS ═══
    // Behavior passed as parameter — strategy pattern in one line
    static String summarize(List<Trade> trades, java.util.function.Predicate<Trade> criteria) {
        return trades.stream().filter(criteria)
            .map(Trade::id).collect(Collectors.joining(", "));
    }

    // ═══ BENEFIT 6: DECLARATIVE STYLE ═══
    // WHAT: "settled trades total" — not HOW to iterate and accumulate
}
