package com.bank.fp;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class FunctionalBenefitsTest {

    @Test void pureFunction_sameInputSameOutput() {
        var total1 = FunctionalBenefitsDemo.calculateTotal(FunctionalBenefitsDemo.trades);
        var total2 = FunctionalBenefitsDemo.calculateTotal(FunctionalBenefitsDemo.trades);
        assertThat(total1).isEqualByComparingTo(total2);  // always same result!
    }

    @Test void parallelProducesSameResult() {
        var seq = FunctionalBenefitsDemo.calculateTotal(FunctionalBenefitsDemo.trades);
        var par = FunctionalBenefitsDemo.calculateTotalParallel(FunctionalBenefitsDemo.trades);
        assertThat(seq).isEqualByComparingTo(par);  // parallel = sequential result
    }

    @Test void higherOrderFunction() {
        var settled = FunctionalBenefitsDemo.summarize(
            FunctionalBenefitsDemo.trades, FunctionalBenefitsDemo.Trade::isSettled);
        assertThat(settled).isEqualTo("T1, T3");

        var all = FunctionalBenefitsDemo.summarize(
            FunctionalBenefitsDemo.trades, t -> true);  // different behavior, same method
        assertThat(all).isEqualTo("T1, T2, T3");
    }
}
