package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class FpBenefitsTest {

    // pure function: output depends only on input, no side effects
    BigDecimal interest(BigDecimal principal) {
        return principal.multiply(new BigDecimal("0.071"));
    }

    @Test
    void pureFunctionDeclarativeAndParallelSafe() {
        List<BigDecimal> balances = List.of(
            new BigDecimal("1000000"), new BigDecimal("250000"));

        BigDecimal total = balances.parallelStream()   // safe: no shared state
            .map(this::interest)                        // pure transform
            .reduce(BigDecimal.ZERO, BigDecimal::add);  // associative

        assertThat(total).isEqualByComparingTo("88750.000");
    }
}
